async def timeout_middleware(request: Request, call_next):
    try:
        start_time = time.time()
        timeout = GLOBAL_REQUEST_TIMEOUT_SECONDS
        if request.url.path.startswith((BROWSER_LIFECYCLE_PREFIX, COMPUTER_LIFECYCLE_PREFIX)):
